var f = createFormat({decimals:3, forceDecimal:true});
var x = createVariable({prefix:"X"}, f);
var out = [];
out.push(x.format(10.5));
out.push(x.format(10.5));
out.push(x.format(10.5004));
out.push(x.format(10.501));
return JSON.stringify(out);

var f = createFormat({decimals:1, forceDecimal:true});
var a = createVariable({prefix:"A"}, f);
var s = createVariable({prefix:"S", force:true}, createFormat({decimals:0}));
var out = [];
out.push(a.format(1));
a.reset();
out.push(a.format(1));
out.push(s.format(12000));
out.push(s.format(12000));
a.disable();
out.push(a.format(9));
a.enable();
out.push(a.format(9));
return JSON.stringify(out);

var retracted = true;
var f = createFormat({decimals:3, forceDecimal:true});
var z = createVariable({onchange:function() {retracted = false;}, prefix:"Z"}, f);
var out = [];
out.push(z.format(15));
out.push(String(retracted));
retracted = true;
out.push(z.format(15)); // suppressed: onchange must NOT fire
out.push(String(retracted));
out.push(z.format(-1));
out.push(String(retracted));
return JSON.stringify(out);

var f = createFormat({decimals:3, forceDecimal:true});
var i = createReferenceVariable({prefix:"I"}, f);
var out = [];
out.push(i.format(5, 0));
out.push(i.format(0, 0));      // equal to reference: suppressed
out.push(i.format(0.0004, 0)); // rounds to reference: suppressed
out.push(i.format(-2.5, 0));
out.push(i.format(7));         // no reference: always out
return JSON.stringify(out);

var gFormat = createFormat({prefix:"G", width:2, zeropad:true, decimals:1});
var gMotion = createModal({}, gFormat);
var out = [];
out.push(gMotion.format(0));
out.push(gMotion.format(0));
out.push(gMotion.format(1));
out.push(String(gMotion.getCurrent()));
gMotion.reset();
out.push(gMotion.format(1));
return JSON.stringify(out);

var gFormat = createFormat({prefix:"G", width:2, zeropad:true, decimals:1});
var gMotion = createModal({}, gFormat);
var gPlane = createModal({onchange:function() {gMotion.reset();}}, gFormat);
var out = [];
out.push(gMotion.format(1));
out.push(gPlane.format(17));
out.push(gMotion.format(1)); // plane change reset the motion modal
out.push(gPlane.format(17)); // suppressed: no reset side effect
out.push(gMotion.format(1)); // suppressed again
return JSON.stringify(out);

