writeBlock(gMotionModal.format(1), xOutput.format(10.5), feedOutput.format(500)); // fully modal: no line
writeBlock(gMotionModal.format(1), xOutput.format(11), feedOutput.format(500));
return JSON.stringify(__ivacTestOutput());

var out = [];
out.push(formatWords("G1", "X10.5", "F500"));
out.push(formatWords(["G1", ["X1", "Y2"], "Z3"]));
out.push(formatWords("A", undefined, null, "", "B"));
function via() { return formatWords(arguments); }
out.push(via("G0", "X0"));
function blocky() { var w = ["N10"]; return formatWords(w, arguments); }
out.push(blocky("G1", "X5"));
