var f = createFormat({decimals:3, forceDecimal:true});
var out = [];
out.push(f.format(1.5));
f.setPrefix("R");
f.setNumberOfDecimals(1);
out.push(f.format(1.55));
f.setForceSign(true);
out.push(f.format(2));
out.push(String(f.getNumberOfDecimals()));
out.push(String(f.getMinimumValue()));
out.push(String(f.areDifferent(1.0004, 1.0)));
out.push(String(f.areDifferent(1.06, 1.0)));
out.push(String(f.isSignificant(0.04)));
out.push(String(f.isSignificant(0.06)));
return JSON.stringify(out);
